contract InvMutTest {
    C c;
    address initialOwner;

    constructor(C _c) { c = _c; initialOwner = c.owner(); }

    // single public function with all test logic
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // record c's state-viewable values before the call
        address ownerBefore = c.owner();
        uint balanceBefore = address(c).balance;

        bool reverted;
        // perform the state-changing call; capture whether it reverted
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable values after the call
        address ownerAfter = c.owner();
        uint balanceAfter = address(c).balance;

        // General rule: either the call reverted, or the owner did not change and the contract ends with zero balance
        assert(reverted || (ownerAfter == ownerBefore && balanceAfter == 0));
    }

    // fallback/receive to accept Ether forwarded by C during its go() call
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept an arbitrary amount to send to c.go
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to forward");

        // read owner and c balance before
        address ownerBefore = c.owner();
        uint256 cBalBefore = address(c).balance;
        uint256 myBalBefore = address(this).balance;

        // perform the call and record whether it reverted
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        address ownerAfter = c.owner();
        uint256 cBalAfter = address(c).balance;
        uint256 myBalAfter = address(this).balance;

        // General rule (single assert): if call reverted then c.balance is unchanged and owner unchanged;
        // otherwise (succeeded) owner unchanged, c holds zero, and this contract's balance did not increase.
        assert(
            (reverted && ownerAfter == ownerBefore && cBalAfter == cBalBefore)
            ||
            (!reverted && ownerAfter == ownerBefore && cBalAfter == 0 && myBalAfter <= myBalBefore)
        );
    }

    // Fallback/receive to allow c to send us ETH during the call (though rule expects it not to increase our balance on success)
    receive() external payable {}
}

