contract InvMutTest {
    C c;
    address origOwner;
    constructor(C _c) { c = _c; origOwner = c.owner(); }
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // record pre-call observable values
        address beforeOwner = c.owner();
        uint256 beforeCbal = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        // make the state-changing call as a top-level statement
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read post-call observables
        address afterOwner = c.owner();
        uint256 afterCbal = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule:
        // 1) owner must never change
        // 2) If call succeeded (not reverted) then C's balance is zero (it forwards funds out)
        // 3) The test contract's balance cannot increase as a result of the call when it succeeded
        //    (any increase is only allowed when the call reverted, representing a refund)
        assert(
            afterOwner == beforeOwner
            && (
                reverted
                ? true
                : (afterCbal == 0 && afterThis <= beforeThis)
            )
        );
    }
    receive() external payable { }
}

